char *numberToBinaryReverse(uint16_t number, int binarySize) {
    char *results = (char*) calloc(sizeof(char), binarySize);

    int pos = binarySize - 1;

    while (number > 0) {
        results[binarySize - pos] = number % 2 == 0 ? ' ' : 'X';
        pos--;
        number /=2;
    }
    return results;
}


int numberTo16BitBinaryReverse(char **result, uint16_t number) {
    int binarySize = 8;
    // char *results = (char*) calloc(sizeof(char), binarySize);

    // int pos = binarySize - 1;
    int pos = BYTE_SIZE - 1;

    // set all values to zero
    memset(*result, '\0', binarySize);

    while (number > 0) {
        (*result)[BYTE_SIZE - pos] = number % 2 == 0 ? '.' : 'X';

        pos--;
        number /=2;
    // printf("Test Value: %d, Result: %s\n", number, results);
    }
    // return results;
    return 0;
}



